    "chat": true,
    "streaming": true,
    "tool_calls": "partial"
  },
  "profiles": [
    {
      "id": "prod",
      "label": "Production",
      "limits": {
        "max_tokens": 65536,
        "recommended_context": 4096
      },
      "runtime_hints": {
        "batch_size": 8,
        "kv_cache_policy": "shared_prefix"
      }
    }
  ],
  "latency_hint": "interactive",
  "quantization_support": [
    "int8",
    "llm-int8"
  ],
  "notes": "v2.1.0 is recommended for low-latency interactive workloads. See profiles for production constraints."
}
